1	package email
2	
3	import (
4		"crypto/tls"
5		"fmt"
6		"log/slog"
7		"net"
8		"net/smtp"
9		"strings"
10		"time"
11	)
12	
13	// SMTPConfig holds SMTP server configuration.
14	type SMTPConfig struct {
15		Host     string
16		Port     int
17		Username string
18		Password string
19		TLS      bool
20	}
21	
22	// Address returns the host:port string.
23	func (c *SMTPConfig) Address() string {
24		return fmt.Sprintf("%s:%d", c.Host, c.Port)
25	}
26	
27	// Sender sends emails via SMTP.
28	type Sender struct {
29		config SMTPConfig
30		logger *slog.Logger
31	}
32	
33	// NewSender creates a new Sender with the given SMTP config and logger.
34	func NewSender(config SMTPConfig, logger *slog.Logger) *Sender {
35		if logger == nil {
36			logger = slog.Default()
37		}
38		return &Sender{config: config, logger: logger}
39	}
40	
41	// Send dispatches an email message.
42	func (s *Sender) Send(msg *Message) error {
43		start := time.Now()
44	
45		if err := msg.Validate(); err != nil {
46			s.logger.Error("message validation failed", "error", err, "subject", msg.Subject)
47			return fmt.Errorf("%w: %v", ErrSendFailed, err)
48		}
49	
50		addr := s.config.Address()
51		recipients := msg.AllRecipients()
52	
53		s.logger.Info("sending email",
54			"from", msg.From,
55			"to", msg.To,
56			"subject", msg.Subject,
57			"smtp", addr,
58		)
59	
60		if err := s.sendSMTP(addr, msg, recipients); err != nil {
61			s.logger.Error("send failed",
62				"error", err,
63				"smtp", addr,
64				"duration", time.Since(start),
65			)
66			return fmt.Errorf("%w: %v", ErrSendFailed, err)
67		}
68	
69		s.logger.Info("email sent",
70			"to", msg.To,
71			"duration", time.Since(start),
72		)
73		return nil
74	}
75	
76	func (s *Sender) sendSMTP(addr string, msg *Message, recipients []string) error {
77		if s.config.TLS {
78			return s.sendWithTLS(addr, msg, recipients)
79		}
80		return s.sendPlain(addr, msg, recipients)
81	}
82	
83	func (s *Sender) sendPlain(addr string, msg *Message, recipients []string) error {
84		conn, err := net.DialTimeout("tcp", addr, 10*time.Second)
85		if err != nil {
86			return fmt.Errorf("%w: %v", ErrConnectFailed, err)
87		}
88		defer conn.Close()
89	
90		client, err := smtp.NewClient(conn, s.config.Host)
91		if err != nil {
92			return fmt.Errorf("creating SMTP client: %w", err)
93		}
94		defer client.Close()
95	
96		if err := s.authenticate(client); err != nil {
97			return err
98		}
99	
100		return s.sendMessage(client, msg, recipients)
101	}
102	
103	func (s *Sender) sendWithTLS(addr string, msg *Message, recipients []string) error {
104		tlsConfig := &tls.Config{ServerName: s.config.Host}
