131	        }
132	
133	        // Drop the sender to signal workers to exit.
134	        {
135	            let mut state = self.state.lock().unwrap();
136	            state.sender.take();
137	        }
138	
139	        // Join worker threads.
140	        let mut state = self.state.lock().unwrap();
141	        for handle in state.workers.drain(..) {
142	            let _ = handle.join();
143	        }
144	    }
145	}
